def set_app_config_listener(topic : DataReader, callback):

    # 3. 构造 Listener，只设置 on_data_available 回调
    listener = Listener(on_data_available=callback)  # :contentReference[oaicite:0]{index=0}

    # 4. 打开 DataReader 的状态掩码，让 “有新数据” 事件生效
