    topic.status_mask = DDSStatus.DataAvailable               # :contentReference[oaicite:1]{index=1}

    # 5. 把 Listener 绑定到 Reader
    topic.set_listener(listener)                               # :contentReference[oaicite:2]{index=2}
    return

