from log import logger
import re

def shell_set_volume(raw_val) :
    # raw_val = str(req.get('value', '')).strip()
            # 只允许 0-100 （可带 % 或不带）
    # m = re.fullmatch(r'(\d{1,3})%', raw_val)
    m = re.search(r'([0-9]+)\s*%', raw_val)
    if m is None :
        return 'format error'

    val = int(m.group(1))
    if val < 0 or val > 100:
        return 'value must be between 0 and 100'

    cmd_val = ''
    if '%+' in raw_val:
        cmd_val = f"{val}%+"
    elif '%-' in raw_val:
        cmd_val = f"{val}%-"
    else:
        cmd_val = f"{val}%"

    cmd = f"amixer set Speaker {cmd_val}"
    perform_cmd(cmd)

def perform_cmd(cmd) :
    try :
        # 执行 'ls -l' 命令
        result = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE)

        # 输出结果
        logger.info(f'cmd: {cmd}, Returned code: {result.returncode}')
    except Exception as e :
        logger.error(f'perform shell error: {e}')

