import socket, threading, sys

LISTEN = ('0.0.0.0', 9991)   # rndis0 口
TARGET = ('192.168.12.1', 9991)

def pipe(a, b):
    try:
        while True:
            d = a.recv(4096)
            if not d: break
            b.sendall(d)
    except OSError:
        pass
    finally:
        for s in (a, b):
            try: s.shutdown(socket.SHUT_RDWR)
            except OSError: pass

srv = socket.socket()
srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
srv.bind(LISTEN); srv.listen(5)
print(f'relay {LISTEN} -> {TARGET}', flush=True)
while True:
    c, _ = srv.accept()
    try:
        t = socket.create_connection(TARGET, timeout=8)
    except OSError as e:
        print('target fail', e, flush=True); c.close(); continue
    threading.Thread(target=pipe, args=(c, t), daemon=True).start()
    threading.Thread(target=pipe, args=(t, c), daemon=True).start()

